/**
 * The typed `/api` surface. Request/response types come from the ts-rs
 * contract under `src/types` (single direction: Rust → TS, regenerated by
 * `cargo test -p i0721-proto -p i0721-server`, never hand-written).
 */
import type {
  AuthSession,
  CreateUserRequest,
  FileDto,
  HealthReport,
  LoginRequest,
  PageResult,
  Role,
  SiteConfig,
  SiteConfigStrict,
  UserDto,
} from "@/types";

import { apiFetch, apiUpload } from "./client";

// ── auth ───────────────────────────────────────────────────────────────

export function login(request: LoginRequest): Promise<AuthSession> {
  return apiFetch<AuthSession>("/api/v1/auth/login", {
    method: "POST",
    body: request,
    anonymous: true,
  });
}

export function verify(): Promise<UserDto> {
  return apiFetch<UserDto>("/api/v1/auth/verify");
}

export function refresh(): Promise<AuthSession> {
  return apiFetch<AuthSession>("/api/v1/auth/refresh", { method: "POST" });
}

// ── files ──────────────────────────────────────────────────────────────

export function listFiles(offset: number, limit: number): Promise<PageResult<FileDto>> {
  return apiFetch<PageResult<FileDto>>(
    `/api/v1/files?offset=${encodeURIComponent(offset)}&limit=${encodeURIComponent(limit)}`,
  );
}

export function uploadFile(file: File, onProgress?: (fraction: number) => void): Promise<void> {
  return apiUpload("/api/v1/files", file, onProgress);
}

export function deleteFile(id: string): Promise<void> {
  return apiFetch<void>(`/api/v1/files/${encodeURIComponent(id)}`, { method: "DELETE" });
}

// ── users ──────────────────────────────────────────────────────────────

export function listUsers(offset: number, limit: number): Promise<PageResult<UserDto>> {
  return apiFetch<PageResult<UserDto>>(
    `/api/v1/users?offset=${encodeURIComponent(offset)}&limit=${encodeURIComponent(limit)}`,
  );
}

export function createUser(request: CreateUserRequest): Promise<UserDto> {
  return apiFetch<UserDto>("/api/v1/users", { method: "POST", body: request });
}

export function deleteUser(id: string): Promise<void> {
  return apiFetch<void>(`/api/v1/users/${encodeURIComponent(id)}`, { method: "DELETE" });
}

// ── settings ───────────────────────────────────────────────────────────

export function getSiteConfig(): Promise<SiteConfig> {
  return apiFetch<SiteConfig>("/api/v1/settings");
}

export function putSiteConfig(strict: SiteConfigStrict): Promise<void> {
  return apiFetch<void>("/api/v1/settings", { method: "PUT", body: strict });
}

export function health(): Promise<HealthReport> {
  return apiFetch<HealthReport>("/api/health", { anonymous: true });
}

export type { Role };
